加载数据：
load data local inpath &#x27;~/student.txt&#x27; into table student;load data local inpath &#x27;~/course.txt&#x27; into table course;load data local inpath &#x27;~/teacher.txt&#x27; into table teacher;load data local inpath &#x27;~/score.txt&#x27; into table score;



表之间的关系如图：



1、查询”01”课程比”02”课程成绩高的学生的信息及课程分数:
SELECT     T0.*,    T1.s_score AS c01,    T2.s_score as c02FROM    student AS T0,    (SELECT s_id,s_score FROM score WHERE c_id=&#x27;01&#x27;) AS T1,    (SELECT s_id,s_score FROM score WHERE c_id=&#x27;02&#x27;) AS T2WHERE T0.s_id=T1.s_idAND T0.s_id=T2.s_idAND T1.s_score&gt;T2.s_score;

运行结果：







2、查询同时存在” 01 “课程和” 02 “课程的情况:
SELECT    t3.*,    t1.s_score as c01,    t2.s_score as c02FROM     (SELECT s_id,s_score FROM score WHERE c_id=&#x27;01&#x27;) as t1, -- 选修01课程的同学    (SELECT s_id,s_score FROM score WHERE c_id=&#x27;02&#x27;) as t2, -- 选修01课程的同学    student as t3WHERE t1.s_id=t2.s_idAND t2.s_id=t3.s_id;

运行结果：





3、查询存在” 01 “课程但可能不存在” 02 “课程的情况(不存在时显示为 null )
SELECT    t2.*,    t1.s_score AS c01,    t3.s_score AS c02 FROM    (SELECT s_id,s_score FROM score WHERE c_id=&#x27;01&#x27;) AS t1, -- 选修01课程的同学    student AS t2LEFT JOIN (SELECT s_id,s_score FROM score WHERE c_id=&#x27;02&#x27;) AS t3 -- 选修01课程的同学ON t2.s_id = t3.s_idWHERE t1.s_id=t2.s_id;

运行结果：




4、查询平均成绩小于60分的同学的学生编号和学生姓名和平均成绩:(包括有成绩的和无成绩的)

SELECT    T1.s_id,    T1.s_name,    T2.avg_scFROM student AS T1JOIN(SELECT        s_id,        avg(s_score) AS avg_sc     FROM score    GROUP BY s_id    having avg_sc&lt;60) AS T2ON T1.s_id=T2.s_id; 

运行结果：




5、查询所有同学的学生编号、学生姓名、选课总数、所有课程的总成绩:
SELECT    T1.s_id,    T1.s_name,    T2.co_cnt,    T3.sum_scoreFROM student AS T1LEFT JOIN (SELECT s_id,count(1) AS co_cnt FROM score GROUP BY s_id) AS T2ON T1.s_id=T2.s_idLEFT JOIN (SELECT s_id,sum(s_score) AS sum_score FROM score GROUP BY s_id) AS T3ON T1.s_id=T3.s_id;

运行结果：



6、查询”李”姓老师的数量:
SELECT COUNT(1) FROM teacher WHERE t_name LIKE &quot;李%&quot;;




7、查询学过”张三”老师授课的同学的信息:
SELECT     T1.*,    T3.c_name,    T4.t_nameFROM    student AS T1,    score AS T2,    course AS T3,    teacher AS T4WHERE T1.s_id=T2.s_idAND T2.c_id=T3.c_idAND T3.t_id=T4.t_idAND T4.t_name=&quot;张三&quot;;

运行结果：



8、查询没学过”张三”老师授课的同学的信息:
SELECT A1.* FROM student AS A1LEFT JOIN(SELECT                 T1.s_id            FROM                student AS T1,                score AS T2,                course AS T3,                teacher AS T4            WHERE T1.s_id=T2.s_id            AND T2.c_id=T3.c_id            AND T3.t_id=T4.t_id            AND T4.t_name=&quot;张三&quot;) AS A2ON A1.s_id=A2.s_idWHERE A2.s_id IS NULL;

运行结果：



9、查询学过编号为”01”并且也学过编号为”02”的课程的同学的信息:
SELECT A.* FROM student AS AJOIN (SELECT            T1.s_id        FROM (SELECT s_id FROM score WHERE c_id=&#x27;01&#x27;) AS T1        JOIN (SELECT s_id FROM score WHERE c_id=&#x27;02&#x27;) AS T2        ON T1.s_id=T2.s_id) AS BON A.s_id=B.s_id;

运行结果：



10、查询学过编号为”01”但是没有学过编号为”02”的课程的同学的信息:
SELECT A.* FROM student AS AJOIN (SELECT            T1.s_id        FROM (SELECT s_id FROM score WHERE c_id=&#x27;01&#x27;) AS T1        LEFT JOIN (SELECT s_id FROM score WHERE c_id=&#x27;02&#x27;) AS T2        ON T1.s_id=T2.s_id        WHERE T2.s_id IS NULL) AS BON A.s_id=B.s_id;

运行结果：






11、查询没有学全所有课程的同学的信息:

SELECT    T1.*,    T2.CNT_CFROM student AS T1LEFT JOIN (SELECT s_id,count(1) AS CNT_C FROM score GROUP BY s_id) AS T2ON T1.s_id=T2.s_idWHERE T2.CNT_C&lt;3;





12、查询至少有一门课与学号为”01”的同学所学相同的同学的信息:

SELECT     t3.*,    t4.cnt FROM student AS t3 JOIN(    SELECT s_id,    COUNT(1) AS cnt     FROM score AS t1     JOIN (SELECT c_id           FROM score          WHERE s_id =&quot;01&quot;) AS t2     ON t1.c_id = t2.c_id     GROUP BY s_id     HAVING cnt&gt;0) AS t4 ON t3.s_id=t4.s_id;





13、查询和”01”号的同学学习的课程完全相同的其他同学的信息:

SELECT     A1.*,    A2.CNT_CFROM student AS A1JOIN (SELECT T1.s_id,count(1) AS CNT_C        FROM score AS T1        JOIN (SELECT c_id FROM score WHERE s_id=&#x27;01&#x27;) AS T2        ON T1.c_id=T2.c_id        GROUP BY T1.s_id) AS A2ON A1.s_id=A2.s_idAND A1.S_id&lt;&gt;&#x27;01&#x27;JOIN (SELECT count(1) AS CNT_C FROM score where s_id=&#x27;01&#x27;) AS A3ON A2.CNT_C=A3.CNT_C;






14、查询没学过”张三”老师讲授的任一门课程的学生姓名:

