17、按平均成绩从高到低显示所有学生的所有课程的成绩以及平均成绩:

尝试用WITH的写法，相对常规写法逻辑还是比较清晰的。
WITH T1 AS (-- 平均分    SELECT        s_id,        AVG(s_score) AS AVG_S    FROM score    GROUP BY s_id), T2 AS(-- 语文分数    SELECT        s_id,        s_score    FROM score    WHERE c_id=&#x27;01&#x27;), T3 AS(-- 数学分数    SELECT        s_id,        s_score    FROM score    WHERE c_id=&#x27;02&#x27;), T4 AS(-- 英语分数    SELECT        s_id,        s_score    FROM score    WHERE c_id=&#x27;03&#x27;)SELECT    T0.s_id,    T0.s_name,    (CASE WHEN T1.AVG_S IS NULL THEN &#x27;0&#x27; ELSE round(T1.AVG_S,2) END) AS AVG_S,    (CASE WHEN T2.s_score IS NULL THEN &#x27;0&#x27; ELSE T2.s_score END) AS CHINESE,    (CASE WHEN T3.s_score IS NULL THEN &#x27;0&#x27; ELSE T3.s_score END) AS MATH,    (CASE WHEN T4.s_score IS NULL THEN &#x27;0&#x27; ELSE T4.s_score END) AS ENGLISHFROM student AS T0LEFT JOIN T1ON T1.s_id=T0.s_idLEFT JOIN T2ON T2.s_id=T0.s_idLEFT JOIN T3ON T3.s_id=T0.s_idLEFT JOIN T4ON T4.s_id=T0.s_idORDER BY AVG_S DESC;







18.查询各科成绩最高分、最低分和平均分：以如下形式显示：课程ID，课程name，最高分， ，平均分，及格率，中等率，优良率，优秀率: （及格为&gt;&#x3D;60，中等为：70-80，优良为：80-90，优秀为：&gt;&#x3D;90）

WITH A1 AS(    SELECT        c_id,        MAX(s_score) AS max_c,        MIN(s_score) AS min_c,        ROUND(AVG(s_score),2)  AS avg_c,        ROUND(SUM(CASE WHEN s_score&gt;=60 THEN 1 ELSE 0 END)/count(s_score),2) AS L1,        ROUND(SUM(CASE WHEN s_score BETWEEN 70 AND 79 THEN 1 ELSE 0 END)/count(s_score),2)  AS L2,        ROUND(SUM(CASE WHEN s_score BETWEEN 80 AND 89 THEN 1 ELSE 0 END)/count(s_score),2)  AS L3,        ROUND(SUM(CASE WHEN s_score&gt;=90 THEN 1 ELSE 0 END)/count(s_score),2)  AS L4    FROM score GROUP BY c_id)SELECT    A0.c_id,    A0.c_name,    A1.max_c,    A1.min_c,    A1.avg_c,    A1.L1,    A1.L2,    A1.L3,    A1.L4FROM course AS A0JOIN A1ON A0.c_id=A1.c_id;





