23、统计各科成绩各分数段人数：课程编号,课程名称,[100-85],[85-70],[70-60],[0-60]及所占百分比

WITH A1 AS(    SELECT        c_id,        SUM(CASE WHEN s_score BETWEEN 0 AND 59 THEN 1 ELSE 0 END) AS L0, -- [0-59分的人数]        ROUND(SUM(CASE WHEN s_score BETWEEN 0 AND 59 THEN 1 ELSE 0 END)/COUNT(1),2) AS H0, -- [0-59分的人数占比]        SUM(CASE WHEN s_score BETWEEN 60 AND 70 THEN 1 ELSE 0 END) AS L1, -- [60-69分的人数]        ROUND(SUM(CASE WHEN s_score BETWEEN 60 AND 69 THEN 1 ELSE 0 END)/COUNT(1),2) AS H1, -- [60-69分的人数占比]        SUM(CASE WHEN s_score BETWEEN 70 AND 85 THEN 1 ELSE 0 END)  AS L2, -- [70-85分的人数]        ROUND(SUM(CASE WHEN s_score BETWEEN 70 AND 85 THEN 1 ELSE 0 END)/COUNT(1),2) AS H2, -- [70-85分的人数占比]        SUM(CASE WHEN s_score BETWEEN 86 AND 100 THEN 1 ELSE 0 END)  AS L3, -- [86-100分的人数]        ROUND(SUM(CASE WHEN s_score BETWEEN 86 AND 100 THEN 1 ELSE 0 END)/COUNT(1),2) AS H3 -- [86-100分的人数占比]    FROM score GROUP BY c_id)SELECT    A0.c_id,    A0.c_name,    A1.L3,    A1.H3,    A1.L2,    A1.H2,    A1.L1,    A1.H1,    A1.L0,    A1.H0FROM course AS A0JOIN A1ON A0.c_id=A1.c_id;






