package tech.mapan.hive;import org.apache.hadoop.hive.ql.exec.UDF;/** * @program: UDF * @description: 地址脱敏, 对长度超过15个字符串, 只保留前15个字符, 不超过15个则不截取, 全部返回。 * @author: MaPan * @create: 2020-03-22 11:19 **/public class MaskAddress extends UDF &#123;    public String evaluate(String s) &#123;        String result = &quot;&quot;;        if (s == null) &#123;            return null;        &#125; else if (s.length() &gt; 15) &#123;            result = s.substring(0, 14);        &#125; else &#123;            result = s;        &#125;        return result;    &#125;&#125;




