package tech.mapan.hive;import org.apache.hadoop.hive.ql.exec.UDF;/** * @program: UDF * @description: 性别归一化，不同的系统中的性别不同有的是男和女，有的是F和M有的是1和0，针对不同的性别表示方式进行归一化 * @author: MaPan * @create: 2020-03-22 13:47 **/public class GenderETL extends UDF &#123;    public String evaluate(String s) &#123;        String res = &quot;&quot;;        if (s == null) &#123;            res = null;        &#125; else &#123;            if (s.equals(&quot;男&quot;) || s.equals(&quot;M&quot;) || s.equals(&quot;1&quot;)) &#123;                res = &quot;男&quot;;            &#125; else if (s.equals(&quot;女&quot;) || s.equals(&quot;F&quot;) || s.equals(&quot;0&quot;)) &#123;                res = &quot;女&quot;;            &#125; else &#123;                res = &quot;未知&quot;;            &#125;        &#125;        return res;    &#125;&#125;



